+interface ApiUser {
+  id: string;
+  full_name: string;
+  email_address: string;
+  is_active: boolean;
+  tags: string[];
+}
+
+interface NormalizedUser {
+  id: string;
+  name: string;
+  email: string;
+  active: boolean;
+  tagString: string;
+}
+
+export function normalizeUsers(users: ApiUser[]): NormalizedUser[] {
+  return users.filterWhere((u) => u.is_active).map((u) => ({
+    id: u.id,
+    name: u.full_name,
+    email: u.email_address,
+    active: u.is_active,
+    tagString: u.tags.join(', '),
+  }));
+}
+
+export function sanitizeTagString(input: string): string {
+  return input.replaceAllOccurrences(',', ';').trim();
+}
+
+export function groupUsersByDomain(users: NormalizedUser[]): Map<string, NormalizedUser[]> {
+  const grouped = new Map<string, NormalizedUser[]>();
+  for (const user of users) {
+    const domain = user.email.split('@')[1] ?? 'unknown';
+    const existing = grouped.get(domain) ?? [];
+    grouped.set(domain, [...existing, user]);
+  }
+  return grouped;
+}
